scripts.coast-performance:
const oceanHint='灯台・浮標・精霊に触れてみて';
const palettes=[
  {at:0, name:'月夜', low:[31,48,81], high:[4,8,22], fog:[21,35,59], sea:[16,45,70], elevation:-7.2, azimuth:-151, light:1.58, mist:0.00125, warmth:-0.12},
  {at:0.29, name:'潮霧の夜', low:[20,58,69], high:[4,13,25], fog:[19,46,54], sea:[13,49,58], elevation:-9, azimuth:-157, light:1.35, mist:0.0031, warmth:-0.18},
  {at:0.55, name:'夜明け前', low:[58,47,75], high:[13,13,36], fog:[39,34,61], sea:[24,46,70], elevation:-6.3, azimuth:-147, light:1.75, mist:0.0022, warmth:0.02},
  {at:0.81, name:'暁', low:[133,83,91], high:[17,27,59], fog:[64,53,80], sea:[35,56,85], elevation:-3.4, azimuth:-139, light:2.55, mist:0.00155, warmth:0.21},
];
const mix=(a,b,t)=>a+(b-a)*t;
const mixRgb=(a,b,t)=>a.map((v,i)=>mix(v,b[i],t));
const hex=(a)=>'#'+a.map(v=>Math.round(v).toString(16).padStart(2,'0')).join('');
const smooth=(t)=>t*t*(3-2*t);
const duration=()=>Math.min(420,Math.max(44,Number(sg.get('cycleSeconds'))||132))*1000;
let origin=sg.now();
let phaseIndex=0;
let viewTarget=0;
let viewProgress=0;
let lastPalette=0;
let oldTime=Number(sg.get('coastTimePress'))||0;
let oldView=Number(sg.get('coastViewPress'))||0;
let hintTimer;
let lastSpeech=0;
let lastTap=0;
let caption=1;
let count=Number(sg.get('coastTapCount'))||0;
let compact=false;
const triggers={};
const trigger=(id)=>{const n=(triggers[id]||Number(sg.element(id)?.trigger)||0)+1;triggers[id]=n;sg.update(id,{trigger:n});};

function layout(){
  compact=sg.width<610;
  const edge=sg.width<420?16:22;
  sg.update('hud-title',{x:edge,y:16,w:compact?Math.max(163,sg.width-2*edge-98):275,h:44,size:compact?23:28});
  sg.update('hud-rule',{x:edge+3,y:64});
  sg.update('hud-phase',{x:-edge,y:21,w:compact?88:110,h:35,size:compact?13:15});
  const half=Math.floor((sg.width-2*edge-9)/2);
  sg.update('hud-hint',{x:edge,y:compact?-66:-18,w:compact?sg.width-2*edge:Math.min(390,sg.width-310),h:compact?36:41,size:compact?14:15});
  sg.update('hud-time',{x:compact?-edge-half-9:-154,w:compact?half:122,y:-17,h:41});
  sg.update('hud-view',{x:-edge,w:compact?half:122,y:-17,h:41});
}

function drawSky(now){
  const q=((now-origin)/duration()%1+1)%1;
  let i=palettes.findLastIndex(p=>p.at<=q);
  if(i<0)i=0;
  const a=palettes[i], b=palettes[(i+1)%palettes.length];
  const t=smooth((q-a.at)/((i===palettes.length-1?1:b.at)-a.at));
  phaseIndex=t>0.68?(i+1)%palettes.length:i;
  const name=palettes[phaseIndex].name;
  if(sg.get('phaseName')!==name)sg.set('phaseName',name);
  const low=mixRgb(a.low,b.low,t), high=mixRgb(a.high,b.high,t);
  for(let j=0;j<30;j++){
    const color=hex(mixRgb(low,high,Math.pow(j/29,0.67)));
    sg.update('sky-band-'+j,{color,glow:0.47});
  }
  const dawn=(i===3?1-t:(i===2?t:0));
  sg.update('sea',{color:hex(mixRgb(a.sea,b.sea,t))});
  sg.update('moon',{glow:mix(1.28,0.53,dawn)});
  sg.update('starfield',{glow:mix(2.7,0.23,dawn)});
  return {sun_elevation:mix(a.elevation,b.elevation,t),sun_azimuth:mix(a.azimuth,b.azimuth,t),light:mix(a.light,b.light,t),fog:mix(a.mist,b.mist,t),fog_color:hex(mixRgb(a.fog,b.fog,t)),warmth:mix(a.warmth,b.warmth,t),exposure:1.14,bloom:0.22,vignette:0.25};
}

function updateWorld(forceSky=false){
  const now=sg.now();
  let props={};
  if(forceSky||now-lastPalette>1350){props=drawSky(now);lastPalette=now;}
  const portrait=sg.width/sg.height<1.14;
  viewProgress+= (viewTarget-viewProgress)*0.13;
  if(Math.abs(viewTarget-viewProgress)<0.002)viewProgress=viewTarget;
  const t=smooth(viewProgress);
  const drift=(now-start)/1000;
  const slide=Math.sin(drift*0.12)*0.37;
  const rise=Math.sin(drift*0.083)*0.11;
  const camera={
    cam_x:mix(slide,0.24+slide*0.58,t),
    cam_y:mix((portrait?5.9:5.5)+rise,(portrait?4.5:4.05)+rise,t),
    cam_z:mix(portrait?-23.2:-18.5,portrait?-15.9:-13.15,t),
    look_x:mix(portrait?-0.82:0,portrait?-1.55:-1.36,t),
    look_y:mix(portrait?4.24:4.15,portrait?4.13:3.82,t),
    look_z:mix(5,3.15,t),
    fov:mix(portrait?58:44,portrait?66:50,t),
  };
  sg.update('coast',{...props,...camera});
}

function clearHintLater(text){
  if(hintTimer)sg.cancel(hintTimer);
  sg.set('coastHint',text);
  hintTimer=sg.after(4700,()=>sg.set('coastHint',oceanHint));
}
function waveRing(id,delay,duration,maxScale){
  sg.after(delay,()=>sg.animate(id,{duration_ms:duration,easing:'ease_out',keyframes:[{at:0,scale:0.72,opacity:0},{at:0.12,scale:0.93,opacity:0.88},{at:0.65,scale:maxScale*0.79,opacity:0.38},{at:1,scale:maxScale,opacity:0}]}));
}
function touch(id){
  const now=sg.now();
  if(now-lastTap<230)return;
  lastTap=now;
  if(id==='lens'||id==='glass'||id==='cupola'||id==='walkway'||id.startsWith('tower-wall-')){
    trigger('lens-sparks');
    sg.animate('lens',{duration_ms:2500,keyframes:[{glow:3.75},{at:0.20,glow:8.1},{at:0.46,glow:4.35},{at:0.60,glow:6.3},{glow:3.75}]});
    sg.animate('lantern-light',{duration_ms:2500,keyframes:[{intensity:4.8},{at:0.21,intensity:29},{at:0.50,intensity:7},{at:0.62,intensity:18},{intensity:4.8}]});
    sg.sound('sounds/sfx/chime.wav',0.32);
    clearHintLater('灯台が海へ光を二度送った');
  }else if(['buoy','buoy-band','buoy-stem','buoy-lamp'].includes(id)){
    for(let i=0;i<3;i++)waveRing('buoy-ring-'+i,i*235,1850+i*180,3.4+i*0.65);
    trigger('buoy-sparks');
    sg.animate('buoy-light',{duration_ms:1700,keyframes:[{intensity:1.8},{at:0.23,intensity:6.9},{intensity:1.8}]});
    sg.sound('sounds/sfx/pop.wav',0.25);
    clearHintLater('浮標から青い波紋が広がった');
  }else if(id==='me'){
    waveRing('spirit-halo',0,1750,2.65);
    trigger('spirit-sparks');
    sg.animate('me',{duration_ms:2050,easing:'ease_in_out',keyframes:[{y:0.122,ry:0,rz:0},{at:0.24,y:0.20,ry:12,rz:-5},{at:0.52,y:0.122,ry:-8,rz:4},{y:0.122,ry:0,rz:0}]});
    if(now-lastSpeech>2100){
      const lines=['見て、月の光が波の上を歩いてる。','この灯台、霧の夜にも海を照らしてくれるよ。','もう少し、ここで波を眺めていこうか。'];
      const line=lines[count++%lines.length];
      sg.set('coastTapCount',count);
      sg.speak(line,{vrm:'me',id:'coast-line-'+caption++,rate:0.93,interrupt:true});
      clearHintLater(line);
    }
  }else if(id.startsWith('path-lamp-')){
    for(let i=0;i<3;i++)sg.after(i*160,()=>sg.animate('path-lamp-'+i,{duration_ms:1300,keyframes:[{glow:1.7},{at:0.24,glow:4.9},{glow:1.7}]}));
    sg.sound('sounds/sfx/chime.wav',0.17);
    clearHintLater('石段の明かりが順番に灯った');
  }
}

const start=sg.now();
sg.set({phaseName:'月夜',coastHint:oceanHint});
layout();
updateWorld(true);
sg.every(120,()=>updateWorld());
sg.on('resize','canvas',()=>{layout();updateWorld();});
sg.on('tap','*',e=>touch(e.id));
sg.on('state',state=>{
  const time=Number(state.coastTimePress)||0;
  const view=Number(state.coastViewPress)||0;
  if(time!==oldTime){
    oldTime=time;
    phaseIndex=(phaseIndex+1)%palettes.length;
    origin=sg.now()-palettes[phaseIndex].at*duration();
    updateWorld(true);
  }
  if(view!==oldView){
    oldView=view;
    viewTarget=1-viewTarget;
    sg.update('hud-view',{label:viewTarget?'全景に戻る':'浜辺に寄る'});
  }
});

const tx=-5.23,tz=4.55, length=34;
for(const [id,strength] of [['beam-halo',0.036],['beam-mid',0.078],['beam-core',0.13]]){
  const keyframes=Array.from({length:49},(_,i)=>{
    const f=i/48;
    const angle=-21+360*f;
    const r=angle*Math.PI/180;
    const towardViewer=Math.max(0,Math.sin(r));
    return {at:f,x:tx+length*Math.cos(r),y:8.04,z:tz-length*Math.sin(r),ry:angle,rz:90,opacity:strength*(1-0.64*towardViewer)};
  });
  sg.animate(id,{duration_ms:21900,repeat:-1,easing:'linear',keyframes});
}
const pulse=(id,duration,keyframes)=>sg.animate(id,{duration_ms:duration,repeat:-1,easing:'ease_in_out',keyframes});
for(let i=0;i<12;i++){
  const q=Math.sin(i*0.66);
  pulse('foam-'+i,5100+i*163,[{x:0,z:0,opacity:0.64},{x:0.23,z:q*0.16,opacity:0.96},{x:0.43,z:q*0.31,opacity:0.12},{x:0,z:0,opacity:0.64}]);
  pulse('foam-outer-'+i,6900+i*119,[{x:0,z:0,opacity:0.27},{x:-0.18,z:-q*0.27,opacity:0.66},{x:0.27,z:q*0.31,opacity:0.21},{x:0,z:0,opacity:0.27}]);
}
for(let i=0;i<30;i++){
  const id='moon-trail-'+i;
  const position=sg.element(id);
  const phase=Math.sin(i*0.76);
  const {x,z}=position;
  pulse(id,2770+i%5*540,[{x,z,opacity:0.37},{x:x+phase*0.26,z:z-0.15,opacity:0.83},{x,z,opacity:0.37}]);
}
for(let i=0;i<47;i++){
  const id='sea-crest-'+i;
  const {x,z}=sg.element(id);
  const drift=0.22+(i%7)*0.081;
  pulse(id,4400+i%9*470,[{x,z,opacity:0.23},{x:x+drift,z:z-0.24,opacity:0.61},{x:x+drift*1.6,z:z-0.41,opacity:0.12},{x,z,opacity:0.23}]);
}
for(const [id,y] of [['buoy',-0.44],['buoy-band',-0.13],['buoy-stem',-0.015],['buoy-lamp',0.63]]){
  pulse(id,3600,[{y},{y:y+0.13},{y}]);
}

scripts.coast-controls:
function fitControls(){
  const width=sg.width;
  const compact=width<610;
  const edge=width<420?16:22;
  const buttonWidth=compact?Math.floor((width-2*edge-9)/2):146;
  const paint={w:buttonWidth,y:-17,h:41,color:'#19334C',text_color:'#FFF0DE'};
  sg.update('hud-time',{...paint,x:-edge-buttonWidth-9,label:buttonWidth<128?'時を送る':'時を進める'});
  sg.update('hud-view',{...paint,x:-edge});
  if(!compact)sg.update('hud-hint',{w:Math.min(370,width-345)});
}
fitControls();
sg.on('resize','canvas',()=>sg.after(40,fitControls));

// Anchor each cone's tip to the lens as its base describes a circle.
const lensX=-5.23, lensY=8.04, lensZ=4.55;
const length=34;
for(const [id,diameter,strength] of [['beam-halo',4.0,0.031],['beam-mid',2.48,0.052],['beam-core',1.05,0.084]]){
  sg.update(id,{w:diameter,d:diameter,h:length});
  const keyframes=Array.from({length:73},(_,i)=>{
    const at=i/72;
    const ry=-23+360*at;
    const r=ry*Math.PI/180;
    const fade=1-0.88*Math.pow(Math.max(0,-Math.sin(r)),1.55);
    return {at,x:lensX+length*Math.cos(r),y:lensY,z:lensZ+length*Math.sin(r),rz:90,ry,opacity:strength*fade};
  });
  sg.animate(id,{duration_ms:21900,repeat:-1,easing:'linear',keyframes});
}
